use std::collections::BTreeMap;
use glam::{Vec2,Vec3};
use crate::{Sim,InputFrame,SimEvent,entity::EntityId,input::buttons as b,puppet::{PuppetDef,BodyPlan}};
use super::{*,data::{distance,flat,toward},weapons::jam_chance};
pub fn detection_rate(distance:f32,posture:u8,grass:f32,hour:f32,sprinting:bool,still:bool,camo:bool,lit:bool)->f32{let stance=match posture{1=>0.6,2=>0.3,_=>1.};let cover=if grass>0.5{if posture>0{0.35}else{0.6}}else{1.};let night=if !(6.0..19.0).contains(&hour){0.45}else{1.};let light=if lit{1.5}else{night};(1.-distance/140.).max(0.).powi(2)*stance*cover*light*if sprinting{1.3}else if still{0.5}else{1.}*if camo{0.7}else{1.}}
impl Merc{
 pub fn ai(&mut self,sim:&mut Sim,dt:f32,events:&mut Vec<SimEvent>,out:&mut BTreeMap<EntityId,InputFrame>){if self.contract==0&&!self.session{return;}let mut attackers=0;let mut pending_damage=Vec::new();let mut dead=Vec::new();let data=self.data.clone();let night=!(6.0..19.0).contains(&self.hour);let player=self.pos;let safe_town=self.safe_town_at(player);let mut bark=None;let mut flags=Vec::new();let group_living:Vec<usize>=(0..data.world.place.len()).map(|g|self.soldiers.iter().filter(|n|n.group==g&&n.hp>0.).count()).collect();let mut radio=Vec::new();
 for (ni,n) in self.soldiers.iter_mut().enumerate(){if n.hp<=0.{continue;}let dist=distance(n.pos,player);let near=dist<80.;if near&&n.entity.is_none(){n.pos.y=terrain::height(&data,n.pos.x,n.pos.z)+0.05;let mut def=PuppetDef::preset(BodyPlan::Biped);def.skin="#644530".into();def.shirt=if n.faction==0{"#59603c"}else{"#82674f"}.into();let id=sim.spawn_npc("soldier",n.pos,n.yaw,def,None,None);n.entity=Some(id);}if !near{if let Some(id)=n.entity.take(){sim.despawn(id);}continue;}
 n.timer=(n.timer-dt).max(0.);n.cooldown=(n.cooldown-dt).max(0.);if n.poison>0.{n.poison-=dt;if n.poison<=0.{dead.push((ni,true));continue;}}
 let burning=self.fire.at(flat(n.pos))==1;if burning{n.burning=3.;}if n.burning>0.{n.burning-=dt;n.hp-=dt*16.;n.state=4;flags.push("enemy_panicked");if n.hp<=0.{dead.push((ni,false));continue;}if sim.state.rng.f32()<dt*0.8{self.fire.ignite(&data,flat(n.pos),0.1);}}
 let f=Vec2::new(n.yaw.sin(),-n.yaw.cos());let dir=toward(n.pos,player);let visible=!self.cheats.invisible&&dist<130.&&f.dot(dir)>-0.5&&!safe_town&&!self.fire.smoke(flat(n.pos),flat(player))&&!crate::projectile::static_blocked(&sim.state.physics,n.pos+Vec3::Y*1.4,(player+Vec3::Y*1.3-n.pos-Vec3::Y*1.4).normalize_or_zero(),(player+Vec3::Y*1.3-n.pos-Vec3::Y*1.4).length(),None);
 if visible{n.detection=(n.detection+dt*self.tuning.detection*detection_rate(dist,self.stance,terrain::grass(&data,flat(player)),self.hour,self.speed>5.5,self.speed<0.3,self.upgrades.contains(&3),self.fire.at(flat(player))==1)*1.25).min(1.);}else{n.detection=(n.detection-dt*0.1).max(0.);}
 if n.detection>=1.&&n.state<2{n.state=2;n.timer=20.;radio.push(n.pos);bark=Some("There. Past the grass.");}else if n.detection>0.2&&n.state==0{n.state=1;n.timer=8.;}
 if n.state==2&&!visible&&n.timer<=0.{n.state=3;n.timer=20.;}else if n.state==3&&n.timer<=0.{n.state=0;n.detection=0.;}
 let low_morale=group_living[n.group]<=2||burning;let mut input=InputFrame::default();let cover=Vec2::new((ni as f32*2.3).cos(),(ni as f32*2.3).sin());
 match n.state {4=>{input.move_dir=-self.wind+cover*0.4;},2=>{n.yaw=dir.x.atan2(-dir.y);if low_morale{input.move_dir=-dir;flags.push("morale_broken");}else if ni%3==0{input.move_dir=Vec2::new(-dir.y,dir.x)*0.6;flags.push("flanker");}else if dist<12.{input.move_dir=-dir*0.4;}else if dist>45.{input.move_dir=dir*0.45;}else{input.held|=b::CROUCH;}
 if n.gun.jammed{if n.timer<=0.{n.gun.jammed=false;n.timer=20.;}else{flags.push("enemy_jam_seen");}}else if visible&&n.cooldown<=0.&&attackers<4 {attackers+=1;if sim.state.rng.f32()<jam_chance(n.gun.condition)*self.tuning.jam{n.gun.jammed=true;n.timer=2.;bark=Some("Not now. Work the bolt.");flags.push("enemy_jam_seen");}else{n.gun.condition=(n.gun.condition-0.14*self.tuning.wear).max(5.);n.cooldown=if n.role==2{2.2}else{0.85+sim.state.rng.f32()};let chance=self.tuning.enemy_accuracy*(1.-dist/200.).max(0.15)*if self.speed>4.{0.45}else{1.}*if night{0.8}else{1.};if sim.state.rng.f32()<chance{pending_damage.push(if n.role==2{18.}else if n.role==3&&self.riding.is_some(){24.}else{8.});}events.push(SimEvent::Shot{pos:n.pos+Vec3::Y*1.4});}}},1|3=>{input.move_dir=dir*0.3;if n.timer<=0.{n.state=0;}},_=>{let target=n.home+Vec3::new((self.time*0.07+ni as f32).sin()*5.,0.,(self.time*0.07+ni as f32).cos()*5.);input.move_dir=toward(n.pos,target)*0.25;}}
 if terrain::water(&data,flat(n.pos)+input.move_dir*3.){input.move_dir=Vec2::new(-input.move_dir.y,input.move_dir.x);}if self.fire.at(flat(n.pos)+input.move_dir*4.)==1{input.move_dir=-self.wind;}
 if let Some(id)=n.entity{out.insert(id,input);}
 }
 for p in radio{for n in &mut self.soldiers{if n.hp>0.&&n.state<2&&distance(n.pos,p)<80.{n.state=2;n.detection=1.;n.timer=20.;}}}
 for amount in pending_damage{self.damage(amount*self.tuning.enemy_damage,0);}for (i,poison) in dead{self.soldiers[i].hp=1.;if poison{self.flag("dart_kill");}self.hit_soldier(sim,i,500.,events);}for flag in flags{self.flag(flag);}if let Some(line)=bark{if self.subtitle_time<=0.{self.say("Soldier",line);}}
 }
 pub fn safe_town_at(&self,p:Vec3)->bool{self.ceasefire&&distance(p,self.data.place("town").pos())<76.}
 pub fn drive(&mut self,sim:&mut Sim,input:&InputFrame,dt:f32,events:&mut Vec<SimEvent>){let Some(i)=self.riding else{return;};let v=&mut self.vehicles[i];if v.exploded{self.riding=None;return;}let throttle=if input.axes!=Vec2::ZERO{input.axes.x-input.axes.y}else{-input.move_dir.y*self.yaw.cos()+input.move_dir.x*self.yaw.sin()};let steer=if input.axes!=Vec2::ZERO{input.move_dir.x}else{input.move_dir.x*self.yaw.cos()+input.move_dir.y*self.yaw.sin()};v.steer=steer;let max=if v.kind==3{16.}else if v.kind==2{18.}else if v.kind==1{30.}else{25.}*self.tuning.vehicle_speed*if v.hp<40.{0.6}else{1.};if self.seat==0{v.speed+=(throttle*max-v.speed)*dt*1.4;if input.down(b::JUMP){v.speed*=(-dt*8.).exp();}v.yaw+=(steer*v.speed*0.035).clamp(-1.5,1.5)*dt;}else{v.speed*=(-dt*1.5).exp();}
 let forward=Vec3::new(v.yaw.sin(),0.,-v.yaw.cos());let next=v.pos+forward*v.speed*dt;if v.kind==3{if terrain::water(&self.data,flat(next)){v.pos=next;v.pos.y=0.25+(self.time*2.).sin()*0.06;}else{v.speed=0.;}}else{if terrain::water(&self.data,flat(next)){v.speed*=0.5;v.hp-=dt;}else{v.pos=next;v.pos.y=terrain::height(&self.data,next.x,next.z);let slope=terrain::height(&self.data,next.x+forward.x*2.,next.z+forward.z*2.)-terrain::height(&self.data,next.x-forward.x*2.,next.z-forward.z*2.);v.pitch+=((-slope/4.).atan()-v.pitch)*(dt*6.).min(1.);v.roll+=(-steer*v.speed*0.006-v.roll)*(dt*5.).min(1.);}}
 self.pos=v.pos;self.pos.y+=0.65;self.speed=v.speed.abs();if self.map_up{self.flag("map_driving");}if input.down(b::PRIMARY)&&self.seat==1{events.push(SimEvent::Shot{pos:self.pos+Vec3::Y*2.});}self.sync_player(sim);}
 pub fn survival(&mut self,sim:&mut Sim,dt:f32,_events:&mut Vec<SimEvent>){if self.health>0.&&self.health<100.&&self.health>=20.{let top=(self.health/20.).ceil()*20.;self.health=(self.health+dt*0.35).min(top);}
 if !self.cheats.fever{self.fever_timer-=dt;if self.fever_state==0&&self.fever_timer<=40.{self.fever_state=1;self.flag("fever_warned");self.say("Field note",self.s("fever_warn").to_string());}if self.fever_timer<=0.&&self.fever_state==1{self.fever_state=2;self.fever_timer=-0.01;self.fever_attacks+=1;}if self.fever_state==2&&self.fever_timer<=-60.{self.fever_state=0;self.fever_timer=self.tuning.fever_interval*0.9f32.powi(self.fever_attacks as i32);self.health=50.;self.diamonds=(self.diamonds as f32*0.8).floor() as i32;self.hour=(self.hour+6.).rem_euclid(24.);let nearest=self.data.world.place.iter().filter(|p|p.kind==3).min_by(|a,b|distance(a.pos(),self.pos).total_cmp(&distance(b.pos(),self.pos))).unwrap();self.pos=nearest.pos()+Vec3::new(0.,0.,20.);self.pos.y=terrain::height(&self.data,self.pos.x,self.pos.z);self.sync_player(sim);self.flag("blackout");self.say("Field note",self.s("blackout").to_string());}}
 if self.rescue_time>0.{self.rescue_time-=dt;if self.session{if self.rescue_time<=0.{if self.team_lives>0{self.team_lives-=1;self.health=50.;self.pos=self.data.place("depot").pos()+Vec3::new(-65.,0.,70.);self.pos.y=terrain::height(&self.data,self.pos.x,self.pos.z);self.sync_player(sim);}else{self.finished=true;self.won=false;}}}else{self.pos-=Vec3::new(self.wind.x,0.,self.wind.y)*dt*2.;self.sync_player(sim);if self.rescue_time<=0.{self.health=50.;self.active=0;self.flag("player_rescued");self.say("Companion",self.s("rescue").to_string());}}}
 let mut dead=false;for c in &mut self.companions{if c.alive&&c.down>0.{c.down-=dt;if c.down<=0.{c.alive=false;dead=true;}}}if dead{self.flag("companion_died");self.say("Radio","No reply. The stool will stay empty.");}
 if self.tracker{let rate=self.tracker_rate();if rate>0.&&(self.time*rate).floor() as i32!=((self.time-dt)*rate).floor() as i32{self.sound(33);}}
 if let Some(w)=self.waypoint{if distance(w,self.pos)<20.{self.flag("gps_followed");}}
 if self.wind_speed>6.{self.flag("wind_rag");}
 }
 pub fn world_tick(&mut self,sim:&mut Sim,dt:f32,events:&mut Vec<SimEvent>){self.hour=(self.hour+dt/60.*self.tuning.clock_speed).rem_euclid(24.);self.world_hours+=dt/60.*self.tuning.clock_speed;self.wind_timer-=dt;if self.wind_timer<=0.{self.wind_timer=sim.state.rng.range(180.,360.);let angle=sim.state.rng.range(-0.6,0.6);self.wind=Vec2::from_angle(self.wind.y.atan2(self.wind.x)+angle);self.wind_speed=sim.state.rng.range(2.,12.);}
 self.weather_time-=dt;if self.weather_time<=0.{self.weather=(self.weather+1)%3;self.weather_time=if self.weather==2{90.}else{sim.state.rng.range(180.,360.)};if self.weather==2{self.sound(34);self.fire.ignite(&self.data,flat(self.pos)+Vec2::new(80.,60.),2.);self.flag("fire_lightning");}}
 if !self.session||self.host{let prior=self.fire.burning();self.fire.step(&self.data,&mut sim.state.rng,&self.tuning,self.wind,self.wind_speed,self.weather==2,dt);if self.weather==2&&prior>0{self.flag("rain_extinguished");}if self.fire.total>=500{self.flag("big_fire");}
 let burning=self.fire.at(flat(self.pos))==1;if burning{self.burning=3.;}if terrain::water(&self.data,flat(self.pos)){self.burning=0.;self.guns[self.active].condition=(self.guns[self.active].condition-dt*0.08).max(0.);}if self.burning>0.{self.burning-=dt;self.damage(self.tuning.burn_damage*dt,2);}
 let mut exploding=Vec::new();for (i,o) in self.objects.iter_mut().enumerate(){if o.exploded{continue;}if self.fire.at(flat(o.pos))==1&&o.fuse<0.{o.fuse=if o.kind==1{3.}else{1.5};}if o.fuse>=0.{o.fuse-=dt;if o.fuse<=0.{o.exploded=true;exploding.push((i,o.pos));}}}for (_,p) in exploding{self.explode(sim,p,8.,160.,events);self.flag("explosion_chain");}
 let mut vexp=Vec::new();for v in &mut self.vehicles{if v.exploded{continue;}if self.fire.at(flat(v.pos))==1{v.hp-=dt*5.;}if v.hp<15.&&v.fuse<0.{v.fuse=8.;}if v.fuse>=0.{v.fuse-=dt;if v.fuse<=0.{v.exploded=true;vexp.push(v.pos);}}}for p in vexp{self.explode(sim,p,7.,180.,events);self.flag("fire_vehicle");}
 let mut post_flags=Vec::new();for post in &mut self.posts{let pi=self.data.world.place.iter().position(|p|p.id==post.place).unwrap();let p=self.data.world.place[pi].pos();let living=self.soldiers.iter().any(|n|n.group==pi&&n.hp>0.);if !living&&!post.cleared{post.cleared=true;post.cleared_at=self.world_hours;post_flags.push("post_cleared");}if post.cleared&&self.world_hours-post.cleared_at>self.tuning.reman_hours&&!post.safe&&distance(p,self.pos)>200.{post.cleared=false;for n in self.soldiers.iter_mut().filter(|n|n.group==pi){n.hp=80.;n.pos=n.home;n.state=0;n.detection=0.;}post_flags.push("post_remanned");}}for flag in post_flags{self.flag(flag);}}
 for a in &mut self.animals{if self.fire.at(flat(a.pos))==1{a.fleeing=8.;}if a.fleeing>0.{a.fleeing-=dt;let dir=toward(self.pos,a.pos);a.pos+=Vec3::new(dir.x,0.,dir.y)*dt*8.;a.yaw=dir.x.atan2(-dir.y);a.pos.y=terrain::height(&self.data,a.pos.x,a.pos.z);}}
 }
 pub fn attract(&mut self,sim:&mut Sim,dt:f32,events:&mut Vec<SimEvent>){let duration:f32=self.data.attract.iter().map(|s|s.seconds).sum();self.attract_time+=dt;if self.attract_time>=duration{self.attract_time-=duration;self.attract_loops+=1;}let mut t=self.attract_time;let mut si=0;for (i,s) in self.data.attract.iter().enumerate(){if t<s.seconds{si=i;break;}t-=s.seconds;}let s=self.data.attract[si].clone();if self.attract_segment!=si{self.attract_segment=si;self.pos=self.data.place(&s.place).pos()+Vec3::new(0.,0.,55.);self.pos.y=terrain::height(&self.data,self.pos.x,self.pos.z);self.hour=s.hour;self.health=100.;self.aiming=false;self.map_up=false;self.action=None;self.riding=None;self.yaw=0.;self.pitch=0.;if s.action=="fire"{self.fire.ignite(&self.data,flat(self.data.place("depot").pos())-Vec2::splat(20.),6.);}if s.action=="heal"{self.action=Some(Action{kind:"wound_0".into(),left:4.,duration:4.,param:0});}if s.action=="map"{self.map_up=true;}if s.action=="rescue"{self.rescue_time=6.;}if s.action=="jam"{self.guns[self.active].jammed=true;}}
 self.pos.x+=dt*0.8;self.pos.y=terrain::height(&self.data,self.pos.x,self.pos.z);self.yaw=(t*0.02).sin()*0.4;self.view_time+=dt;self.fire.step(&self.data,&mut sim.state.rng,&self.tuning,self.wind,8.,false,dt);if s.action=="jam"&&t>4.{self.guns[self.active].jammed=false;}if s.action=="drive"||s.action=="boat"{self.pos.z-=dt*4.;}self.sync_player(sim);let _=events;}
}
